input.command:
cd /tmp/fceval-i5-t1-61_bwjpm/work && firecrawl scrape "https://chromewebstore.google.com/search/tab%20manager?itemTypes=EXTENSION" --format links -o .firecrawl/l2.json --max-age 0 >/dev/null; firecrawl interact --timeout 280 --code '
let clicks=0;
for (let i=0;i<40;i++){ const b=page.getByRole("button",{name:/load more/i}); if(!await b.count()) break; await b.first().click(); clicks++; await page.waitForTimeout(2000);}
const l=await page.$$eval("a[href*=\"/detail/\"]",as=>[...new Set(as.map(a=>a.href))]);
console.log(JSON.stringify({clicks,n:l.length,l}));' -o .firecrawl/morelinks2.txt >/dev/null; firecrawl interact stop >/dev/null 2>&1; grep -o '"clicks":[0-9]*,"n":[0-9]*' .firecrawl/morelinks2.txt

